package com.meerkattrading.tws;

import junit.framework.TestSuite;

/**
 * Replays the order condition calls recorded in orders-calls.json (generated by
 * {@link TestbedOrderConditions}, see ./gradlew generateOrderCalls) through the
 * {@link Interpreter}, checking each placeOrder reaches the client unchanged.
 */
public class TestOrderCalls extends TestClientCalls {

	private static final String ORDERS_CALLS_JSON = "orders-calls.json";

	public static TestSuite suite() {
		return suite(ORDERS_CALLS_JSON, TestOrderCalls::new);
	}

	public TestOrderCalls(String name) {
		super(ORDERS_CALLS_JSON, name);
	}
}
